 {title:'Sprache und Audio',fields:[['stt.model','STT-Modell','select',['tiny','base','small','medium','large']],['stt.silence_threshold','Stille-Schwelle','number'],['stt.chunk_duration','Chunk-Dauer (Sekunden)','number'],['stt.show_volume_meter','Pegelanzeige','checkbox'],['tts.voice','Desktop-TTS-Stimme','text'],['audio_routing.private_device','Privates Audiogeraet','text'],['audio_routing.public_device','Oeffentliches Audiogeraet','text']]},
 {title:'Proaktiv und Oberflaechen',fields:[['proactive.heartbeat_enabled','Heartbeat aktiv','checkbox'],['proactive.bubbles_enabled','Bubbles aktiv','checkbox'],['proactive.visuals_enabled','Visuelle Hinweise aktiv','checkbox'],['proactive.interval_minutes','Heartbeat-Intervall (Minuten)','number'],['system.mode','Modus','select',['office','lecture','chat']],['system.eyes_ui_enabled','Augen-UI','checkbox'],['system.classic_ui_enabled','ClassicUI','checkbox'],['system.web_ui_enabled','WebUI','checkbox'],['system.terminal_cli_enabled','Terminal-CLI','checkbox'],['system.show_terminal','Terminalfenster anzeigen','checkbox'],['system.windows_speech_enabled','Windows-Spracheingabe','checkbox']]},
